{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Basic Editor role assigned at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The project-wide roles/editor basic role grants both users broad modification permissions across many Google Cloud services, exceeding least-privilege access."
    },
    {
      "check_id": "CKV_GCP_49",
      "title": "Project-level role permits service account management",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The broad roles/editor assignment can provide service account management capabilities at project scope, increasing the risk of privilege escalation or unauthorized workload identity changes."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/browser\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}\n",
  "fix_summary": "Replaced the project-level basic Editor role with the narrower predefined Browser role. This removes broad resource modification and service account management capabilities while retaining project resource discovery access."
}
